import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { jobSeeker } from 'src/app/auth/Models/jobSeeker';
import { Job } from 'src/app/landing/models/job';
import { CompanyService } from 'src/app/service/company/company.service';
import { JobService } from 'src/app/service/job/job.service';
import { JobseekerService } from 'src/app/service/jobseeker/jobseeker.service';
import { SeekerService } from 'src/app/service/seeker/seeker.service';

@Component({
  selector: 'app-my-profile',
  templateUrl: './my-profile.component.html',
  styleUrls: ['./my-profile.component.css']
})
export class MyProfileComponent {
constructor(private seekerService : SeekerService,  private router: Router, private jobService: JobService,
    private companyService: CompanyService, private jobSeekerService : JobseekerService ){}



jobSeeker! : jobSeeker;
getJobseekerById(id : number){
this.seekerService.getSeekerById(id).subscribe({
  next : (result) => {
   this.jobSeeker = result;
  },
  error : (err) => {console.log(err);}
});
}


allJobs: Job[] = [];

  isLoggedIn = false;
  initials = '';
  profileRoute = '/';







  ngOnInit(): void {


    const jobseekerId = Number(localStorage.getItem('id'));
  this.getJobseekerById(jobseekerId);

    this.isLoggedIn = !!localStorage.getItem('token');

    if (this.isLoggedIn) {

      const role = localStorage.getItem('role');
      const id = Number(localStorage.getItem('id'));

      if (role === 'COMPANY') {

        this.profileRoute = '/company/dashboard';

        this.companyService.getCompanyById(id).subscribe({
          next: (company: any) => {
            if (company?.companyName) {
              this.initials = company.companyName
                .split(' ')
                .map((x: string) => x.charAt(0))
                .join('')
                .substring(0, 2)
                .toUpperCase();
            }
          },
          error: (err) => console.error(err)
        });

      } else {

        this.profileRoute = '/seeker/dashboard';

        this.jobSeekerService.getJobSeekerById(id).subscribe({
          next: (user: any) => {


            const name =
              user.userName ??
              `${user.firstName ?? ''} ${user.lastName ?? ''}`.trim();

            if (name) {
              this.initials = name
                .split(' ')
                .map((x: string) => x.charAt(0))
                .join('')
                .substring(0, 2)
                .toUpperCase();
            }
          },
          error: (err) => console.error(err)
        });
      }
    }

    this.getAllJobs();
  }
totaljobs! : Number;

  getAllJobs(): void {
    this.jobService.getAllJobs().subscribe(res => {
      this.allJobs = res;
      this.totaljobs = this.allJobs.length;
    });
  }



  logout(): void {
    localStorage.clear();
    this.router.navigate(['/']);
  }

  goToProfile(): void {
    this.router.navigate([this.profileRoute]);
  }
}
