<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>My Profile · HireHub</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap" rel="stylesheet">

</head>
<body>
<div class="page">
<header class="topnav app">
  <div class="wrap">
    <a href="seeker-dashboard.html" class="brand"><span class="brand-dot"></span>HireHub</a>
    <nav class="nav-links app-links">
      <a href="seeker-dashboard.html">Dashboard</a>
      <a href="seeker-jobs.html">Find Jobs</a>
      <a href="seeker-applications.html">Applications</a>
      <a href="seeker-saved.html">Saved</a>
      <a href="seeker-profile.html" class="active">Profile</a>
    </nav>
    <div class="avatar">{{initials}}</div>
  </div>
</header>
<div class="app-shell">
<aside class="sidebar">
  <div class="sidebar-group">
    <span class="sidebar-label">General</span>
    <a href="seeker-dashboard.html"><span class="dot"></span>Dashboard</a>
    <a href="seeker-jobs.html"><span class="dot"></span>Browse Jobs</a>
    <a href="seeker-saved.html"><span class="dot"></span>Saved Jobs</a>
  </div>
  <div class="sidebar-group">
    <span class="sidebar-label">Career</span>
    <a href="seeker-applications.html"><span class="dot"></span>My Applications</a>
    <a href="seeker-profile.html" class="active"><span class="dot"></span>My Profile</a>
    <a href="seeker-resume.html"><span class="dot"></span>Resume &amp; Photo</a>
  </div>
</aside>
<main class="main">

<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:24px;">
  <div style="display:flex;gap:16px;align-items:center;">
    <div class="avatar" style="width:52px;height:52px;font-size:16px;">{{initials}}</div>
    <div><h2 style="font-size:20px;">{{jobSeeker.firstName}} {{jobSeeker.lastName}}</h2><p class="muted" style="font-size:13.5px;">{{jobSeeker.location}}, IN</p></div>
  </div>
  <a href="seeker-profile-edit.html" class="btn btn-secondary btn-sm">Edit profile</a>
</div>
<div class="card-row">
  <div class="card">
    <h3 style="font-size:14px;margin-bottom:8px;">Contact</h3>
    <p style="font-size:13.5px;">{{jobSeeker.email}}</p>
  </div>
  <div class="card">
    <h3 style="font-size:14px;margin-bottom:8px;">Skills</h3>
    <div class="skill-tags">
        <span *ngFor="let skill of jobSeeker?.skills" class="skill-tag">{{skill}}</span>

    </div>
  </div>
</div>
<div class="card" style="margin-top:20px;max-width:520px;">
  <h3 style="font-size:14px;margin-bottom:8px;">Resume</h3>
  <p style="font-size:13.5px;">{{jobSeeker.resumeUrl}} · Uploaded 12 Jun 2026</p>
</div>

</main>
</div>
</div>
</body>
</html>
